import pandas as pd
import numpy as np
import json
from scipy import stats as scipy_stats

df = pd.read_csv('/data/df.csv')

result = {
    "eda_summary": {},
    "correlations": {},
    "trends": [],
    "segments": [],
    "anomalies": [],
    "statistical_tests": [],
    "forecast_points": [],
    "distributions": {},
    "head_preview": [],
    "dtypes_summary": {},
    "missing_pct": {},
    "assumptions": [],
}

try:
    df['reading_time'] = pd.to_datetime(df['reading_time'])
except Exception:
    pass

# Filter to valid row_kind if column exists
try:
    if 'row_kind' in df.columns:
        df = df[~df['row_kind'].isin(['test', 'non_product', 'other_currency', 'cancel', 'refunded'])]
except Exception:
    pass

metric_cols = ['temperature', 'vibration', 'failure']

# EDA
try:
    for col in metric_cols:
        s = df[col].dropna()
        result['eda_summary'][col] = {
            'mean': float(s.mean()),
            'std': float(s.std()),
            'min': float(s.min()),
            'max': float(s.max()),
            'median': float(s.median()),
            'count': int(s.count())
        }
except Exception:
    pass

# Correlations
try:
    num_df = df[metric_cols].dropna()
    pairs = [('temperature', 'vibration'), ('temperature', 'failure'), ('vibration', 'failure')]
    for c1, c2 in pairs:
        r = float(num_df[c1].corr(num_df[c2]))
        if abs(r) >= 0.2:
            result['correlations'][f'{c1}__{c2}'] = round(r, 4)
except Exception:
    pass

# Segmentation
try:
    seg_col = 'line'
    for metric in metric_cols:
        agg = 'mean' if metric in ['temperature', 'vibration'] else 'sum'
        grp = df.groupby(seg_col)[metric].agg(agg).reset_index()
        grp = grp.sort_values(metric, ascending=False).head(10)
        result['segments'].append({
            'segment_column': seg_col,
            'metric_column': metric,
            'aggregation': agg,
            'label': None,
            'results': [{'name': str(r_[seg_col]), 'value': float(r_[metric])} for _, r_ in grp.iterrows()]
        })
    # Failure rate per line
    fail_rate = df.groupby(seg_col)['failure'].mean().reset_index()
    result['segments'].append({
        'segment_column': seg_col,
        'metric_column': 'failure',
        'aggregation': 'ratio',
        'label': 'failure_rate',
        'results': [{'name': str(r_[seg_col]), 'value': float(r_['failure'])} for _, r_ in fail_rate.iterrows()]
    })
except Exception:
    pass

# Anomalies
try:
    anomaly_records = []
    for col in metric_cols:
        s = df[col].dropna()
        if s.nunique() < 5:
            continue
        skew = float(s.skew())
        if abs(skew) > 2:
            shift = -s.min() if s.min() < 0 else 0
            s_t = np.log1p(s + shift)
        else:
            s_t = s
            shift = 0
        q1, q3 = s_t.quantile(0.25), s_t.quantile(0.75)
        iqr = q3 - q1
        lo, hi = q1 - 3 * iqr, q3 + 3 * iqr
        flagged = s_t[(s_t < lo) | (s_t > hi)]
        if len(flagged) / len(s_t) > 0.05:
            anomaly_records.append({
                'column': col, 'row_index': None, 'value': None,
                'expected_range': f'{float(s.min()):.2f}–{float(s.max()):.2f}',
                'severity': 'low',
                'explanation': f'{col} is heavy-tailed; extreme values are a natural distribution, not flagged individually.'
            })
            continue
        if abs(skew) > 2:
            lo_orig = np.expm1(lo) - shift
            hi_orig = np.expm1(hi) - shift
        else:
            lo_orig, hi_orig = lo, hi
        exp_range = f'{lo_orig:.2f}–{hi_orig:.2f}'
        lo5, hi5 = q1 - 5 * iqr, q3 + 5 * iqr
        lo4, hi4 = q1 - 4 * iqr, q3 + 4 * iqr
        for idx in flagged.index:
            val_t = s_t[idx]
            val_orig = float(df.loc[idx, col])
            if val_t > hi5 or val_t < lo5:
                sev = 'critical'
            elif val_t > hi4 or val_t < lo4:
                sev = 'high'
            else:
                sev = 'medium'
            anomaly_records.append({
                'column': col, 'row_index': int(idx), 'value': val_orig,
                'expected_range': exp_range, 'severity': sev,
                'explanation': f'{col} value {val_orig} lies outside expected range {exp_range}.'
            })
            if len(anomaly_records) >= 25:
                break
        if len(anomaly_records) >= 25:
            break
    result['anomalies'] = anomaly_records[:25]
except Exception:
    pass

# Trends (7d rolling per metric)
try:
    df_t = df.set_index('reading_time').sort_index()
    for metric in ['temperature', 'vibration']:
        roll = df_t[metric].resample('D').mean().rolling(7).mean().dropna()
        if len(roll) >= 2:
            pct = float((roll.iloc[-1] - roll.iloc[0]) / roll.iloc[0] * 100)
            direction = 'up' if pct > 1 else ('down' if pct < -1 else 'flat')
            result['trends'].append({
                'column': metric, 'period': '7d_rolling',
                'direction': direction, 'pct_change': round(pct, 2), 'segment': None
            })
    # Failure sum trend MoM
    df_t2 = df.copy()
    df_t2['month'] = df_t2['reading_time'].dt.to_period('M')
    fail_mom = df_t2.groupby('month')['failure'].sum().sort_index()
    if len(fail_mom) >= 2:
        pct_f = float((fail_mom.iloc[-1] - fail_mom.iloc[-2]) / max(fail_mom.iloc[-2], 1) * 100)
        direction_f = 'up' if pct_f > 1 else ('down' if pct_f < -1 else 'flat')
        result['trends'].append({
            'column': 'failure', 'period': 'MoM',
            'direction': direction_f, 'pct_change': round(pct_f, 2), 'segment': None
        })
except Exception:
    pass

# Forecasting (simple linear extrapolation on daily mean temperature and vibration)
try:
    from scipy import stats as sp_stats
    df_fc = df.set_index('reading_time').sort_index()
    for metric in ['temperature', 'vibration']:
        daily = df_fc[metric].resample('D').mean().dropna().reset_index()
        daily['t'] = np.arange(len(daily))
        slope, intercept, _, _, _ = sp_stats.linregress(daily['t'], daily[metric])
        next_t = len(daily)
        next_val = float(intercept + slope * next_t)
        next_date = (daily['reading_time'].iloc[-1] + pd.Timedelta(days=1)).strftime('%Y-%m-%d')
        result['forecast_points'].append({'period': f'{next_date}_{metric}', 'value': round(next_val, 3)})
except Exception:
    pass

result['assumptions'] = [
    "Failure column treated as binary flag; summed for totals, averaged for rates.",
    "Temperature and vibration are readings; averaged across sensors per period.",
    "Anomaly detection uses 3×IQR extreme boundary; log1p applied when |skew|>2.",
    "7-day rolling trend computed on daily means; MoM failure uses calendar months.",
    "Forecast is a linear extrapolation on daily means — suitable only for short horizons."
]

# ─── Guaranteed EDA + chart distributions + briefing (always runs) ───

try:
    _head_df = df.head(5).replace({float('nan'): None})
    result['head_preview'] = _head_df.to_dict('records')
except Exception:
    pass

try:
    result['dtypes_summary'] = {str(k): str(v) for k, v in df.dtypes.items()}
    result['non_null'] = {str(k): int(v) for k, v in df.notna().sum().items()}
    result['n_rows'] = int(len(df))
except Exception:
    pass

try:
    _miss = df.isna().mean() * 100
    result['missing_pct'] = {str(k): round(float(v), 2) for k, v in _miss.items()}
except Exception:
    pass

try:
    if 'temperature' in df.columns and pd.api.types.is_numeric_dtype(df['temperature']):
        _s = df['temperature'].dropna()
        if len(_s) > 0 and 'temperature' not in result['eda_summary']:
            result['eda_summary']['temperature'] = {
                'mean': round(float(_s.mean()), 4),
                'std': round(float(_s.std()), 4),
                'min': round(float(_s.min()), 4),
                'max': round(float(_s.max()), 4),
                'median': round(float(_s.median()), 4),
                'count': int(_s.count()),
            }
except Exception:
    pass

try:
    if 'vibration' in df.columns and pd.api.types.is_numeric_dtype(df['vibration']):
