                'max': round(float(_s.max()), 4),
                'median': round(float(_s.median()), 4),
                'count': int(_s.count()),
            }
except Exception:
    pass

try:
    if 'failure' in df.columns and pd.api.types.is_numeric_dtype(df['failure']):
        _s = df['failure'].dropna()
        if len(_s) > 0 and 'failure' not in result['eda_summary']:
