                'expected_range': f'{float(s.min()):.2f}–{float(s.max()):.2f}',
                'severity': 'low',
                'explanation': f'{col} is heavy-tailed; extreme values are a natural distribution, not flagged individually.'
            })
            continue
        if abs(skew) > 2:
            lo_orig = np.expm1(lo) - shift
            hi_orig = np.expm1(hi) - shift
        else:
            lo_orig, hi_orig = lo, hi
        exp_range = f'{lo_orig:.2f}–{hi_orig:.2f}'
        lo5, hi5 = q1 - 5 * iqr, q3 + 5 * iqr
        lo4, hi4 = q1 - 4 * iqr, q3 + 4 * iqr
        for idx in flagged.index:
            val_t = s_t[idx]
            val_orig = float(df.loc[idx, col])
            if val_t > hi5 or val_t < lo5:
                sev = 'critical'
            elif val_t > hi4 or val_t < lo4:
                sev = 'high'
            else:
                sev = 'medium'
            anomaly_records.append({
                'column': col, 'row_index': int(idx), 'value': val_orig,
                'expected_range': exp_range, 'severity': sev,
                'explanation': f'{col} value {val_orig} lies outside expected range {exp_range}.'
            })
            if len(anomaly_records) >= 25:
                break
        if len(anomaly_records) >= 25:
            break
    result['anomalies'] = anomaly_records[:25]
except Exception:
    pass

# Trends (7d rolling per metric)
try:
    df_t = df.set_index('reading_time').sort_index()
    for metric in ['temperature', 'vibration']:
        roll = df_t[metric].resample('D').mean().rolling(7).mean().dropna()
        if len(roll) >= 2:
            pct = float((roll.iloc[-1] - roll.iloc[0]) / roll.iloc[0] * 100)
            direction = 'up' if pct > 1 else ('down' if pct < -1 else 'flat')
            result['trends'].append({
                'column': metric, 'period': '7d_rolling',
                'direction': direction, 'pct_change': round(pct, 2), 'segment': None
            })
    # Failure sum trend MoM
    df_t2 = df.copy()
    df_t2['month'] = df_t2['reading_time'].dt.to_period('M')
    fail_mom = df_t2.groupby('month')['failure'].sum().sort_index()
    if len(fail_mom) >= 2:
        pct_f = float((fail_mom.iloc[-1] - fail_mom.iloc[-2]) / max(fail_mom.iloc[-2], 1) * 100)
        direction_f = 'up' if pct_f > 1 else ('down' if pct_f < -1 else 'flat')
        result['trends'].append({
            'column': 'failure', 'period': 'MoM',
            'direction': direction_f, 'pct_change': round(pct_f, 2), 'segment': None
        })
except Exception:
    pass

# Forecasting (simple linear extrapolation on daily mean temperature and vibration)
try:
    from scipy import stats as sp_stats
    df_fc = df.set_index('reading_time').sort_index()
    for metric in ['temperature', 'vibration']:
        daily = df_fc[metric].resample('D').mean().dropna().reset_index()
        daily['t'] = np.arange(len(daily))
        slope, intercept, _, _, _ = sp_stats.linregress(daily['t'], daily[metric])
        next_t = len(daily)
        next_val = float(intercept + slope * next_t)
        next_date = (daily['reading_time'].iloc[-1] + pd.Timedelta(days=1)).strftime('%Y-%m-%d')
        result['forecast_points'].append({'period': f'{next_date}_{metric}', 'value': round(next_val, 3)})
except Exception:
    pass

result['assumptions'] = [
    "Failure column treated as binary flag; summed for totals, averaged for rates.",
    "Temperature and vibration are readings; averaged across sensors per period.",
    "Anomaly detection uses 3×IQR extreme boundary; log1p applied when |skew|>2.",
    "7-day rolling trend computed on daily means; MoM failure uses calendar months.",
    "Forecast is a linear extrapolation on daily means — suitable only for short horizons."
]
