                agg_fn = 'sum'
            grp = df_prod.groupby(seg)[metric]
            if agg_fn == 'mean':
                agg_res = grp.mean()
            else:
                agg_res = grp.sum()
            top = agg_res.nlargest(10)
            segs.append({
                "segment_column": seg,
                "metric_column": metric,
                "aggregation": agg_fn,
                "label": None,
                "results": [{"name": str(k), "value": float(v)} for k, v in top.items()]
            })
    # OEE by Line
    for seg in seg_cols:
        grp = df_prod.groupby(seg)
        oee_results = []
        for name, g in grp:
            run = g['Planned Minutes'].sum() - g['Unplanned Downtime (min)'].sum() - g['Changeover (min)'].sum()
            planned = g['Planned Minutes'].sum()
            oee_val = (g['Ideal Cycle Time (s)'] * g['Good Count']).sum() / 60.0 / planned if planned > 0 else float('nan')
            oee_results.append({"name": str(name), "value": round(float(oee_val), 4)})
        segs.append({
            "segment_column": seg,
            "metric_column": "Good Count",
            "aggregation": "ratio",
            "label": "oee",
            "results": oee_results
        })
    result['segments'] = segs
except Exception:
