try:
    anomalies = []
    skip_cols = set()
    for col in metric_cols:
        s = df_prod[col].dropna()
        if s.nunique() < 5:
            skip_cols.add(col)
            continue
        skew = float(s.skew())
        shift = 0
        if s.min() < 0:
            shift = -s.min() + 1
        if abs(skew) > 2:
            s_t = np.log1p(s + shift)
        else:
            s_t = s.copy()
        q1, q3 = s_t.quantile(0.25), s_t.quantile(0.75)
        iqr = q3 - q1
        lo, hi = q1 - 3 * iqr, q3 + 3 * iqr
        mask = (s_t < lo) | (s_t > hi)
        if mask.sum() / len(s_t) > 0.05:
            anomalies.append({
                "column": col, "row_index": None, "value": None,
                "expected_range": f"heavy-tailed distribution",
                "severity": "low",
                "explanation": f"{col} is heavy-tailed; extreme values are natural, not flagged individually"
            })
            continue
        if abs(skew) > 2:
            lo_orig = float(np.expm1(lo) - shift)
            hi_orig = float(np.expm1(hi) - shift)
        else:
            lo_orig, hi_orig = float(lo), float(hi)
        flagged = s_t[mask]
        q1_5, q3_5 = q1 - 5 * iqr, q3 + 5 * iqr
        q1_4, q3_4 = q1 - 4 * iqr, q3 + 4 * iqr
        for idx in flagged.index[:25]:
            val_t = s_t[idx]
            val_orig = float(df_prod.loc[idx, col])
            if val_t > q3_5 or val_t < q1_5:
                sev = "critical"
            elif val_t > q3_4 or val_t < q1_4:
                sev = "high"
            else:
                sev = "medium"
            exp_range = f"[{lo_orig:.2f}, {hi_orig:.2f}]"
            anomalies.append({
                "column": col, "row_index": int(idx), "value": val_orig,
                "expected_range": exp_range, "severity": sev,
                "explanation": f"{col} value {val_orig} lies outside expected range {exp_range}"
            })
        if len(anomalies) >= 25:
            break
    result['anomalies'] = anomalies[:25]
except Exception:
