metric_cols = ['Planned Minutes', 'Unplanned Downtime (min)', 'Changeover (min)',
               'Total Count', 'Good Count', 'Scrap Count', 'Ideal Cycle Time (s)',
               'Failures', 'Stops']
seg_cols = ['Shift', 'Line', 'Machine']

# EDA
try:
    eda = {}
    for col in metric_cols:
        s = df_prod[col].dropna()
        eda[col] = {
            "mean": float(s.mean()), "std": float(s.std()),
            "min": float(s.min()), "max": float(s.max()),
            "median": float(s.median()), "count": int(s.count())
        }
    result['eda_summary'] = eda
except Exception:
    pass

# Correlations
try:
    corr_dict = {}
    num_df = df_prod[metric_cols].dropna()
    for i, c1 in enumerate(metric_cols):
        for c2 in metric_cols[i+1:]:
            pair = num_df[[c1, c2]].dropna()
            if len(pair) < 10:
                continue
            r, _ = stats.pearsonr(pair[c1], pair[c2])
            if abs(r) >= 0.2:
                corr_dict[f"{c1}__{c2}"] = round(float(r), 4)
    result['correlations'] = corr_dict
except Exception:
    pass

# Segmentation
try:
    segs = []
    for seg in seg_cols:
        for metric in metric_cols:
            if metric == 'Ideal Cycle Time (s)':
                agg_fn = 'mean'
            else:
                agg_fn = 'sum'
            grp = df_prod.groupby(seg)[metric]
            if agg_fn == 'mean':
                agg_res = grp.mean()
            else:
                agg_res = grp.sum()
            top = agg_res.nlargest(10)
            segs.append({
                "segment_column": seg,
                "metric_column": metric,
                "aggregation": agg_fn,
                "label": None,
                "results": [{"name": str(k), "value": float(v)} for k, v in top.items()]
            })
    # OEE by Line
    for seg in seg_cols:
        grp = df_prod.groupby(seg)
        oee_results = []
        for name, g in grp:
            run = g['Planned Minutes'].sum() - g['Unplanned Downtime (min)'].sum() - g['Changeover (min)'].sum()
            planned = g['Planned Minutes'].sum()
            oee_val = (g['Ideal Cycle Time (s)'] * g['Good Count']).sum() / 60.0 / planned if planned > 0 else float('nan')
            oee_results.append({"name": str(name), "value": round(float(oee_val), 4)})
        segs.append({
            "segment_column": seg,
            "metric_column": "Good Count",
            "aggregation": "ratio",
            "label": "oee",
            "results": oee_results
        })
    result['segments'] = segs
except Exception:
    pass

# Anomalies
try:
    anomalies = []
    skip_cols = set()
    for col in metric_cols:
        s = df_prod[col].dropna()
        if s.nunique() < 5:
            skip_cols.add(col)
            continue
        skew = float(s.skew())
        shift = 0
        if s.min() < 0:
            shift = -s.min() + 1
        if abs(skew) > 2:
            s_t = np.log1p(s + shift)
        else:
            s_t = s.copy()
        q1, q3 = s_t.quantile(0.25), s_t.quantile(0.75)
        iqr = q3 - q1
        lo, hi = q1 - 3 * iqr, q3 + 3 * iqr
        mask = (s_t < lo) | (s_t > hi)
        if mask.sum() / len(s_t) > 0.05:
            anomalies.append({
                "column": col, "row_index": None, "value": None,
                "expected_range": f"heavy-tailed distribution",
                "severity": "low",
