        q1_5, q3_5 = q1 - 5 * iqr, q3 + 5 * iqr
        q1_4, q3_4 = q1 - 4 * iqr, q3 + 4 * iqr
        for idx in flagged.index[:25]:
            val_t = s_t[idx]
            val_orig = float(df_prod.loc[idx, col])
            if val_t > q3_5 or val_t < q1_5:
                sev = "critical"
            elif val_t > q3_4 or val_t < q1_4:
                sev = "high"
            else:
                sev = "medium"
            exp_range = f"[{lo_orig:.2f}, {hi_orig:.2f}]"
            anomalies.append({
                "column": col, "row_index": int(idx), "value": val_orig,
                "expected_range": exp_range, "severity": sev,
                "explanation": f"{col} value {val_orig} lies outside expected range {exp_range}"
            })
        if len(anomalies) >= 25:
            break
    result['anomalies'] = anomalies[:25]
except Exception:
    pass

# Trends (7d rolling on key metrics)
try:
    df_prod['_date'] = pd.to_datetime(df_prod['Production Date'])
    daily = df_prod.groupby('_date').agg(
        good_count=('Good Count', 'sum'),
        unplanned=('Unplanned Downtime (min)', 'sum'),
        failures=('Failures', 'sum')
    ).sort_index()
    trends = []
    for col, label in [('good_count', 'Good Count'), ('unplanned', 'Unplanned Downtime (min)'), ('failures', 'Failures')]:
        rolled = daily[col].rolling(7).mean().dropna()
        if len(rolled) >= 2:
            first_val = float(rolled.iloc[0])
            last_val = float(rolled.iloc[-1])
            if first_val != 0:
                pct = (last_val - first_val) / abs(first_val) * 100
            else:
                pct = 0.0
            direction = "up" if pct > 1 else ("down" if pct < -1 else "flat")
            trends.append({
                "column": label, "period": "7d_rolling",
                "direction": direction, "pct_change": round(pct, 2), "segment": None
            })
    result['trends'] = trends
except Exception:
    pass

# Forecasting (simple linear extrapolation on Good Count monthly)
try:
    df_prod['_month'] = pd.to_datetime(df_prod['Production Date']).dt.to_period('M')
    monthly_good = df_prod.groupby('_month')['Good Count'].sum().sort_index()
    if len(monthly_good) >= 2:
        x = np.arange(len(monthly_good))
        y = monthly_good.values.astype(float)
        slope, intercept, _, _, _ = stats.linregress(x, y)
        next_x = len(monthly_good)
        next_period = str(monthly_good.index[-1] + 1)
        forecast_val = float(intercept + slope * next_x)
        result['forecast_points'] = [{"period": next_period, "value": round(forecast_val, 2)}]
except Exception:
    pass

result['assumptions'] = [
    "Only product rows (row_kind in sale/return/refunded/other_currency) used for all analyses.",
    "OEE computed as sum(ideal_cycle_s * good_count)/60 / sum(planned_minutes) per segment.",
    "Ideal Cycle Time (s) aggregated as mean in segmentation, not summed.",
    "7-day rolling trend uses daily totals; direction threshold is ±1% change.",
    "Forecast uses linear regression on monthly Good Count totals; one period ahead only."
]

