    shift = max(0.0, -float(rh_s.min())) + 1e-9
    if abs(skew) > 2:
        transformed = np.log1p(rh_s + shift)
    else:
        transformed = rh_s.copy()
    q1, q3 = transformed.quantile(0.25), transformed.quantile(0.75)
    iqr = q3 - q1
    lo3, hi3 = q1 - 3 * iqr, q3 + 3 * iqr
    lo4, hi4 = q1 - 4 * iqr, q3 + 4 * iqr
    lo5, hi5 = q1 - 5 * iqr, q3 + 5 * iqr
    extreme_mask = (transformed < lo3) | (transformed > hi3)
    pct_extreme = extreme_mask.sum() / len(transformed)
    if pct_extreme > 0.05:
        result['anomalies'].append({
            "column": col, "row_index": None, "value": None,
            "expected_range": "heavy-tailed",
            "severity": "low",
            "explanation": f"{col} is heavy-tailed; more than 5% of values fall outside the 3×IQR boundary"
        })
    else:
        if abs(skew) > 2:
            lo_orig = round(float(np.expm1(lo3) - shift), 4)
            hi_orig = round(float(np.expm1(hi3) - shift), 4)
        else:
            lo_orig = round(float(lo3), 4)
            hi_orig = round(float(hi3), 4)
        flagged_idx = rh_s[extreme_mask].index.tolist()[:25]
        for idx in flagged_idx:
            raw_val = round(float(rh_s.loc[idx]), 4)
            t_val = float(transformed.loc[idx])
            if t_val < lo5 or t_val > hi5:
                sev = "critical"
            elif t_val < lo4 or t_val > hi4:
                sev = "high"
            else:
                sev = "medium"
            result['anomalies'].append({
                "column": col, "row_index": int(idx), "value": raw_val,
                "expected_range": f"{lo_orig} to {hi_orig} hours",
                "severity": sev,
                "explanation": f"{col} value {raw_val} lies outside expected range {lo_orig} to {hi_orig} hours"
