import pandas as pd
import numpy as np
import json
from scipy import stats as scipy_stats

df = pd.read_csv('/data/df.csv')

result = {
    "eda_summary": {},
    "correlations": {},
    "trends": [],
    "segments": [],
    "anomalies": [],
    "statistical_tests": [],
    "forecast_points": [],
    "distributions": {},
    "head_preview": [],
    "dtypes_summary": {},
    "missing_pct": {},
    "assumptions": [],
}

try:
    df['Timestamp'] = pd.to_datetime(df['Timestamp'])
except Exception:
    pass

metric_cols = ['Temperature', 'Vibration (mm/s)', 'Pressure (bar)', 'Alarm']
segment_cols = ['Sensor', 'Line', 'Quality']

# EDA
try:
    eda = {}
    for col in metric_cols:
        s = df[col].dropna()
        eda[col] = {
            "mean": float(s.mean()), "std": float(s.std()),
            "min": float(s.min()), "max": float(s.max()),
            "median": float(s.median()), "count": int(s.count())
        }
    result['eda_summary'] = eda
except Exception:
    pass

# CORRELATIONS
try:
    num_df = df[metric_cols].dropna()
    corr_dict = {}
    cols = metric_cols
    for i in range(len(cols)):
        for j in range(i+1, len(cols)):
            c1, c2 = cols[i], cols[j]
            r = float(num_df[c1].corr(num_df[c2]))
            if abs(r) >= 0.2:
                corr_dict[f"{c1}__{c2}"] = round(r, 4)
    result['correlations'] = corr_dict
except Exception:
    pass

# SEGMENTATION
try:
    segs = []
    for seg_col in segment_cols:
        for metric in metric_cols:
            agg = 'sum' if metric == 'Alarm' else 'mean'
            grp = df.groupby(seg_col)[metric].agg(agg).dropna()
            top = grp.nlargest(10)
            segs.append({
                "segment_column": seg_col,
                "metric_column": metric,
                "aggregation": agg,
                "label": None,
                "results": [{"name": str(k), "value": round(float(v), 4)} for k, v in top.items()]
            })
    result['segments'] = segs
except Exception:
    pass

# ANOMALIES
try:
    anomalies = []
    skippable = ['Alarm']
    check_cols = [c for c in metric_cols if c not in skippable]
    total_cap = 25

    for col in check_cols:
        if total_cap <= 0:
            break
        s = df[col].dropna()
        if s.nunique() < 5:
            continue
        skew = float(s.skew())
        use_log = abs(skew) > 2
        if use_log:
            shift = max(0, -s.min()) + 1
            ts = np.log1p(s + shift)
        else:
            ts = s
            shift = 0
        Q1, Q3 = ts.quantile(0.25), ts.quantile(0.75)
        IQR = Q3 - Q1
        lo3, hi3 = Q1 - 3*IQR, Q3 + 3*IQR
        lo4, hi4 = Q1 - 4*IQR, Q3 + 4*IQR
        lo5, hi5 = Q1 - 5*IQR, Q3 + 5*IQR
        mask = (ts < lo3) | (ts > hi3)
        flagged_frac = mask.sum() / len(ts)
        if flagged_frac > 0.05:
            anomalies.append({
                "column": col, "row_index": None, "value": None,
                "expected_range": f"{float(s.quantile(0.25)):.3f}–{float(s.quantile(0.75)):.3f}",
                "severity": "low",
                "explanation": f"{col} is heavy-tailed; extreme-value flagging skipped."
            })
            continue
        flagged_idx = ts[mask].index
        col_cap = min(total_cap, len(flagged_idx))
        for idx in flagged_idx[:col_cap]:
            tv = ts[idx]
            orig_val = float(s[idx])
            if use_log:
                lo_orig = float(np.expm1(lo3) - shift)
                hi_orig = float(np.expm1(hi3) - shift)
            else:
                lo_orig = float(lo3)
                hi_orig = float(hi3)
            if tv > hi5 or tv < lo5:
                sev = "critical"
            elif tv > hi4 or tv < lo4:
                sev = "high"
            else:
                sev = "medium"
            exp_range = f"{lo_orig:.3f}–{hi_orig:.3f}"
            anomalies.append({
                "column": col, "row_index": int(idx), "value": orig_val,
                "expected_range": exp_range, "severity": sev,
                "explanation": f"{col} value {orig_val:.3f} lies outside expected range {exp_range}."
            })
        total_cap -= col_cap
    result['anomalies'] = anomalies
except Exception:
    pass

# TRENDS (7d rolling)
try:
    trends = []
    df_t = df.set_index('Timestamp').sort_index()
    for col in metric_cols:
        s = df_t[col].dropna().resample('D').mean()
        roll = s.rolling(7).mean().dropna()
        if len(roll) < 2:
