        first_val = float(roll.iloc[0])
        last_val = float(roll.iloc[-1])
        if first_val == 0:
            pct = 0.0
        else:
            pct = round((last_val - first_val) / abs(first_val) * 100, 2)
        direction = 'up' if pct > 1 else ('down' if pct < -1 else 'flat')
        trends.append({
            "column": col, "period": "7d_rolling", "direction": direction,
            "pct_change": pct, "segment": None
        })
    result['trends'] = trends
except Exception:
    pass

# FORECASTING (simple linear extrapolation, next 3 months)
try:
