        x = np.arange(len(ms))
        y = ms.values
        slope, intercept, _, _, _ = sp_stats.linregress(x, y)
        last_period = ms.index[-1]
        for i in range(1, 4):
            next_period = last_period + i * ms.index.freq if hasattr(ms.index, 'freq') and ms.index.freq else last_period + np.timedelta64(30*i, 'D')
            pred = float(intercept + slope * (len(ms) - 1 + i))
            fp.append({"period": str(next_period)[:7], "value": round(pred, 4)})
    result['forecast_points'] = fp
except Exception:
    pass

